      notaRef.current = `${notaRef.current ? notaRef.current + "\n" : ""}${envelopeDoNovoCapitulo(cap.reg, cap.forma, { anos: cap.anos, heroiAnterior: cap.heroiAnterior, cidade: cidadeAtualRef.current })}`;
