      setMundo(sv.mundo || { genero: "Fantasia medieval" }); setNomeCampanha(sv.nomeCampanha || "Aventura"); setPersonagem(pers);
      mensagensRef.current = Array.isArray(sv.mensagens) ? sv.mensagens : [];
